/**
 * Real answers from the recorded 182-query sentence panel (dfo-apis
 * tests/fixtures/sentence_panel/*.jsonl.gz, branch feat/sentence-render-split):
 * the envelope's composed `sentence_plan` verbatim, less empty `entity_refs`,
 * and each part trimmed to its status, variable text, departures and warning
 * codes and severities. `satisfies` checks every one against types.ts.
 */

import type { Part, SentenceToken } from '../../types.ts';

export type PanelAnswer = {
    query: string;
    rendered_sentence: string;
    sentence_plan: SentenceToken[];
    parts: Pick<Part, 'status' | 'variable_text' | 'departures' | 'warnings'>[];
};

